#include <stdio.h>
#include <stdlib.h>

#define MAX_ITEMS 8

int main(void)
{
    char line[512];
    int values[MAX_ITEMS];
    size_t count = 0;
    char *p;

    if (!fgets(line, sizeof line, stdin))
        return 1;
    p = line;
    while (*p != '\0' && *p != '\n') {
        char *end;
        long value = strtol(p, &end, 10);
        if (end == p || count == MAX_ITEMS)
            return 1;
        values[count++] = (int)value;
        if (*end == '\n' || *end == '\0')
            break;
        if (*end != ',')
            return 1;
        p = end + 1;
    }
    printf("%zu values\n", count);
    return 0;
}

